class Cache(ttl, clock):
    def __init__(self, ttl, clock):
        self.ttl = ttl
        self._clock = clock
        self._expiry = self._clock()

    def set(self, key, value):
        self._expiry = self._clock()
        return self.get(key, value)

    def get(self, key, default=None):
        value = self._clock().get(self._expiry)
        if value is None:
            return default
        return value

